Hypothesis Hhd32 : (hd <= 32 * wpls)%Z.
Hypothesis Hs : (128 <= s)%Z.
Hypothesis Hs64 : (s < 2 ^ 64)%Z.
Hypothesis Hbelow : (datad + kd <= s - 80)%Z.
Hypothesis RWD : rdn SEGS mB (Z_to_bv 64 (s - 60)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 wd)).
Hypothesis RHD : rdn SEGS mB (Z_to_bv 64 (s - 64)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 hd)).

(* [comment removed for export] *)
Definition FTc (m : word -> option byte) : Prop := forall a : word, ~ (datad <= u a < datad + 4 * wpld * hd)%Z -> m a = mB a.

Lemma FTc_cell : forall m (a : Z), FTc m -> (s - 80 <= a)%Z -> (a + 4 <= s)%Z -> rdn SEGS m (Z_to_bv 64 a) 4 = rdn SEGS mB (Z_to_bv 64 a) 4.
Proof using Hbelow Hs64 Hs Hkd kd.
