Lemma cc_bits_W : forall (n : nat) (r0 r : bvmap 5 word) (m : word -> option byte) (v : word) (k mm j : Z),
  W C A m md -> POSTM C Ar s mB m -> FTc m ->
  (0 <= j < wd)%Z -> (0 <= k)%Z -> (32 * k + 32 <= hd)%Z -> (0 <= mm)%Z -> (Z.of_nat n = 31 - mm)%Z ->
  regs_agree (fun x => In x [7; 19; 20; 21; 31]%list) r0 r ->
  getr r 30 = v_lw v -> getr r 31 = Z_to_bv 64 mm -> getr r 7 = Z_to_bv 64 (datad + 4 * wpld * (hd - 1 - (32 * k + mm))) ->
  getr r 6 = Z_to_bv 64 (- j - 1) -> getr r 14 = Z_to_bv 64 (- (4 * wpld)) -> getr r 13 = Z_to_bv 64 32 -> getr r 2 = Z_to_bv 64 (s - 80) ->
  (forall m' r', W C A m' md -> POSTM C Ar s mB m' -> FTc m' -> regs_agree (fun x => In x [7; 19; 20; 21; 31]%list) r0 r' ->
     getr r' 7 = Z_to_bv 64 (datad + 4 * wpld * (hd - 1 - (32 * k + 32))) ->
     realizes SEGS (mkCfg (mkst r' (0x87bcc : word) m' al_rom) md) S) ->
  realizes SEGS (mkCfg (mkst r (0x87bf8 : word) m al_rom) md) S.
