Lemma cc_tail_W : forall (n : nat) (r0 r : bvmap 5 word) (m : word -> option byte) (i j : Z),
  W C A m md -> POSTM C Ar s mB m -> FTc m ->
  (0 <= j < wd)%Z -> (0 <= i)%Z -> (Z.of_nat n = hd - 1 - i)%Z ->
  regs_agree (fun x => In x [7; 19; 29; 30; 31]%list) r0 r ->
  getr r 30 = Z_to_bv 64 i -> getr r 28 = Z_to_bv 64 (datas + 4 * wpls * (wd - 1 - j)) ->
  getr r 7 = Z_to_bv 64 (datad + 4 * wpld * (hd - 1 - i)) -> getr r 29 = Z_to_bv 64 hd -> getr r 14 = Z_to_bv 64 (- (4 * wpld)) ->
  getr r 6 = Z_to_bv 64 (- j - 1) -> getr r 2 = Z_to_bv 64 (s - 80) ->
  (forall m' r', W C A m' md -> POSTM C Ar s mB m' -> FTc m' -> regs_agree (fun x => In x [7; 19; 29; 30; 31]%list) r0 r' ->
     getr r' 29 = Z_to_bv 64 hd ->
     realizes SEGS (mkCfg (mkst r' (0x87b8c : word) m' al_rom) md) S) ->
  realizes SEGS (mkCfg (mkst r (0x87c44 : word) m al_rom) md) S.
